SELECT

FROM sekai_dataobject_anime_quote


        (content LIKE CONCAT('%', #{keyword}, '%')
        OR character_name LIKE CONCAT('%', #{keyword}, '%'))


        AND series_id = #{seriesId}


        AND character_id = #{characterId}


ORDER BY series_id, episode, time_point, id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT count(1)
FROM sekai_dataobject_anime_quote


        (content LIKE CONCAT('%', #{keyword}, '%')
        OR character_name LIKE CONCAT('%', #{keyword}, '%'))


        AND series_id = #{seriesId}


        AND character_id = #{characterId}

